package com.smartproperty.platform.residency.controller;
import com.smartproperty.platform.residency.dto.*;import com.smartproperty.platform.residency.service.ResidenceManagementService;import com.smartproperty.platform.residency.vo.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/admin/residence-management") public class ResidenceManagementController {private final ResidenceManagementService service;public ResidenceManagementController(ResidenceManagementService s){service=s;}@GetMapping("/people") public List<PersonOptionVO> people(@RequestParam(required=false)String keyword){return service.searchPeople(keyword);}@PostMapping("/people") public PersonOptionVO create(@Valid @RequestBody CreatePersonRequest r){return service.createPerson(r);}@GetMapping("/available-properties") public List<AvailablePropertyVO> available(@RequestParam Long personId,@RequestParam MoveInRequest.MoveInType moveInType){return service.availableProperties(personId,moveInType);}@PostMapping("/move-ins") public MoveInResultVO moveIn(@Valid @RequestBody MoveInRequest r){return service.moveIn(r);}@PostMapping("/residences/{id}/move-out") public void moveOut(@PathVariable Long id,@Valid @RequestBody MoveOutRequest r){service.moveOut(id,r);}}
